#include <stdio.h>
#include <stdbool.h>

void print_array(const int a[], int n) {
    for (int i = 0; i < n; i++)
        printf("%d ", a[i]);
    printf("\n");
}

void bubble_sort(int a[], int n) {
    for (int pass = 0; pass < n - 1; pass++) {
        bool swapped = false;
        for (int j = 0; j < n - 1 - pass; j++) {
            if (a[j] > a[j + 1]) {
                int temp = a[j];
                a[j] = a[j + 1];
                a[j + 1] = temp;
                swapped = true;
            }
        }
        printf("After pass %d: ", pass + 1);
        print_array(a, n);
        if (!swapped)
            break;
    }
}

int main(void) {
    int marks[] = {5, 2, 9, 1, 6, 3};
    int n = sizeof(marks) / sizeof(marks[0]);

    printf("Before:       ");
    print_array(marks, n);
    bubble_sort(marks, n);
    return 0;
}

